package com.system.location.service.core.gnss

import java.io.ByteArrayInputStream
import java.util.Base64
import java.util.zip.ZipInputStream

/**
 * Last-resort copy of the small immutable GNSS resources for injected processes whose class
 * loader does not expose the module APK (LSPosed system_server). It is generated from
 * core/src/main/resources/gnss and must stay byte-identical to those files.
 */
internal object BundledGnssFallback {
    private val files: Map<String, String> by lazy {
        val decoded = Base64.getDecoder().decode(ARCHIVE)
        val result = LinkedHashMap<String, String>()
        ZipInputStream(ByteArrayInputStream(decoded)).use { input ->
            while (true) {
                val entry = input.nextEntry ?: break
                result[entry.name] = input.readBytes().toString(Charsets.UTF_8)
            }
        }
        result
    }

    fun read(name: String): String? = files[name]

    private const val ARCHIVE = ""
}